1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Locality;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.model.Sha256;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	/**
13	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}: REGION is
14	 * the region code derived from the owner's postcode (see {@link Locality#regionOf}) and
15	 * HASH8 is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the
16	 * concatenation of the owner's normalized (E.164) telephone and lastName (e.g.
17	 * {@code NSW-1A2B3C4D}). When the computed code collides with an existing owner's
18	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more
19	 * that makes it unique. Runs after {@link BuildOwner} (so the telephone is already
20	 * normalized) and before {@link SaveOwner}.
21	 */
22	public class AssignCustomerCode {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String region = Locality.regionOf(owner.getPostcode());
26	        String hash8 = hash8(nullToEmpty(owner.getTelephone()) + nullToEmpty(owner.getLastName()));
27	        String base = region + "-" + hash8;
28	        owner.setCustomerCode(deduplicate(base, existingCodes(ownerRepository)));
29	    }
30	
31	    private static Set<String> existingCodes(OwnerRepository ownerRepository) {
32	        Set<String> codes = new HashSet<>();
33	        for (Owner existing : ownerRepository.findAll()) {
34	            String code = existing.getCustomerCode();
35	            if (code != null) {
36	                codes.add(code);
37	            }
38	        }
39	        return codes;
40	    }
41	
42	    /** Returns {@code base}, or {@code base-<n>} with the smallest {@code n >= 2} not in {@code taken}. */
43	    private static String deduplicate(String base, Set<String> taken) {
44	        if (!taken.contains(base)) {
45	            return base;
46	        }
47	        for (int n = 2; ; n++) {
48	            String candidate = base + "-" + n;
49	            if (!taken.contains(candidate)) {
50	                return candidate;
51	            }
52	        }
53	    }
54	
55	    private static String nullToEmpty(String value) {
56	        return value == null ? "" : value;
57	    }
58	
59	    /** The first 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
60	    private static String hash8(String value) {
61	        return Sha256.hex(value).substring(0, 8).toUpperCase();
62	    }
63	}
