1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.MembershipLevel;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Assigns the owner's {@code membershipLevelCap}: the ceiling applied to a new owner's
10	 * derived {@link MembershipLevel} so it cannot exceed one above the current maximum
11	 * membership level among their existing household members. The cap is
12	 * {@code maxExistingHouseholdMemberLevel + 1}; when the owner has no existing household
13	 * member the cap is left {@code null} and no ceiling applies.
14	 *
15	 * <p>Runs after {@link AssignHousehold} (so the shared {@code householdId} is set) and
16	 * {@link AssignHouseholdSize}, and before {@link SaveOwner}, so the maximum is taken over
17	 * the owners that existed before this create (the new owner is not yet persisted). A
18	 * soft-deleted owner is not a household member and is ignored. The value is fixed at
19	 * creation time and persisted with the owner; {@link MembershipLevel#of(Owner)} then
20	 * bounds the returned level by it.
21	 */
22	public class AssignMembershipLevelCap {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String householdId = owner.getHouseholdId();
26	        if (householdId == null) {
27	            return; // not linked into a household: no ceiling
28	        }
29	        Integer maxLevel = null;
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isDeleted()) {
32	                continue; // a soft-deleted owner is no longer a household member
33	            }
34	            if (householdId.equals(existing.getHouseholdId())) {
35	                int level = MembershipLevel.of(existing);
36	                if (maxLevel == null || level > maxLevel) {
37	                    maxLevel = level;
38	                }
39	            }
40	        }
41	        if (maxLevel != null) {
42	            owner.setMembershipLevelCap(maxLevel + 1);
43	        }
44	    }
45	}
