3	/**
4	 * Derives an owner's numeric membership level from their {@link MembershipPoints}.
5	 *
6	 * <p>Maps points to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
7	 *
8	 * <p>The points-derived level is then bounded by the owner's household level ceiling, if
9	 * one was set at creation (see {@code AssignMembershipLevelCap}): a new owner's level
10	 * cannot exceed one above the maximum level among their existing household members. When
11	 * no ceiling was recorded (the owner had no existing household member) the level is
12	 * uncapped.
13	 */
14	public final class MembershipLevel {
15	
16	    private MembershipLevel() {
17	    }
18	
19	    /** The membership level for the given owner, bounded by the household ceiling if set. */
20	    public static int of(Owner owner) {
21	        int level = fromPoints(MembershipPoints.of(owner));
22	        Integer cap = owner.getMembershipLevelCap();
23	        return cap == null ? level : Math.min(level, cap);
24	    }
25	
26	    /** Maps membership points to a membership level. */
27	    public static int fromPoints(int points) {
28	        if (points <= 1) {
29	            return 1;
30	        }
31	        if (points <= 3) {
32	            return 2;
33	        }
34	        if (points <= 5) {
35	            return 3;
36	        }
37	        return 4;
38	    }
39	}
