2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives an owner's fiscal year from their (business-day-adjusted) registrationDate.
8	 *
9	 * <p>The fiscal year starts on 1 July and is labelled by the calendar year in which it
10	 * ends: a date on or after 1 July falls in the fiscal year ending the following 30 June.
11	 * For example 1 July 2025 and 12 September 2025 both fall in fiscal year 2026, while 30
12	 * June 2025 falls in fiscal year 2025.
13	 *
14	 * <p>{@link #of(Owner)} formats this as {@code 'FY<YY>'} (the two-digit ending year, e.g.
15	 * {@code 'FY26'}); {@link #yearOf(LocalDate)} exposes the four-digit ending year for
16	 * callers that build their own segments (such as the membership number).
17	 */
18	public final class FiscalYear {
19	
20	    /** The month on whose first day the fiscal year begins. */
21	    private static final int START_MONTH = Month.JULY.getValue();
22	
23	    private FiscalYear() {
24	    }
25	
26	    /** The fiscal year label ({@code 'FY<YY>'}) for the owner, or null when unregistered. */
27	    public static String of(Owner owner) {
28	        LocalDate registrationDate = owner.getRegistrationDate();
29	        if (registrationDate == null) {
30	            return null;
31	        }
32	        return "FY" + String.format("%02d", yearOf(registrationDate) % 100);
33	    }
34	
35	    /** The fiscal year (the calendar year it ends in) that {@code date} falls in. */
36	    public static int yearOf(LocalDate date) {
37	        return date.getMonthValue() >= START_MONTH ? date.getYear() + 1 : date.getYear();
38	    }
39	}
