1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Derives an owner's locality (region), preferring the postcode: the postcode range is
8	 * looked up first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the
9	 * postcode is absent or in no known range does it fall back to the fixed city-to-region
10	 * table. This returns the same region for known cities but disambiguates cities that
11	 * share a name.
12	 */
13	public final class Locality {
14	
15	    /** A postcode must be exactly four digits to derive a region. */
16	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
17	
18	    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
19	    private static final Map<String, String> CITY_REGION = Map.of(
20	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
21	
22	    /** Region -> inclusive 4-digit postcode range {low, high}. */
23	    private static final Map<String, int[]> REGION_RANGE = Map.of(
24	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
25	
26	    /** Returned when the region can be derived from neither postcode nor city. */
27	    public static final String UNKNOWN = "UNKNOWN";
28	
29	    private Locality() {
30	    }
31	
32	    /**
33	     * The canonical region string for the given city, or {@link #UNKNOWN} when the
34	     * city is null or not in the fixed city-to-region table.
35	     */
36	    public static String of(String city) {
37	        if (city == null) {
38	            return UNKNOWN;
39	        }
40	        return CITY_REGION.getOrDefault(city, UNKNOWN);
41	    }
42	
43	    /**
44	     * The canonical region string derived from the postcode range first (NSW 2000-2099,
45	     * VIC 3000-3099, QLD 4000-4099), falling back to the city-to-region table when the
46	     * postcode is null, malformed, or in no known range. {@link #UNKNOWN} when neither
47	     * yields a region.
48	     */
49	    public static String of(String city, String postcode) {
50	        String byPostcode = fromPostcode(postcode);
51	        if (!UNKNOWN.equals(byPostcode)) {
52	            return byPostcode;
53	        }
54	        return of(city);
55	    }
56	
57	    /**
58	     * The canonical region string derived from the postcode alone (NSW 2000-2099,
59	     * VIC 3000-3099, QLD 4000-4099), with no city fallback. This is the REGION segment
60	     * of an owner's {@code customerCode}. {@link #UNKNOWN} when the postcode is null,
61	     * malformed, or in no known range.
62	     */
63	    public static String regionOf(String postcode) {
64	        return fromPostcode(postcode);
65	    }
66	
67	    /**
68	     * The owner's locality, taken from the REGION segment of its {@code customerCode}
69	     * (the new region-and-hash identity). When the owner has no customer code (e.g. a
70	     * record created before an identity was assigned) it falls back to deriving the
71	     * region from the owner's postcode and city.
72	     */
73	    public static String of(Owner owner) {
74	        String customerCode = owner.getCustomerCode();
75	        if (customerCode != null) {
76	            int dash = customerCode.indexOf('-');
77	            if (dash > 0) {
78	                return customerCode.substring(0, dash);
79	            }
80	        }
81	        return of(owner.getCity(), owner.getPostcode());
82	    }
83	
84	    /** Region whose range contains the 4-digit postcode, or {@link #UNKNOWN}. */
85	    private static String fromPostcode(String postcode) {
86	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
87	            return UNKNOWN;
88	        }
89	        int value = Integer.parseInt(postcode);
90	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
91	            int[] range = entry.getValue();
92	            if (value >= range[0] && value <= range[1]) {
93	                return entry.getKey();
94	            }
95	        }
96	        return UNKNOWN;
97	    }
98	}
