3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Lower-case hexadecimal SHA-256 of a string's UTF-8 bytes — the one place the digest is
9	 * computed for the values several derived fields hang off (an owner's {@code householdId}
10	 * and the HASH segment of its {@code customerCode}). Callers that want a shorter code take
11	 * a prefix of {@link #hex(String)} (and upper-case it where required), keeping the digest
12	 * itself in a single place rather than re-deriving it per field.
13	 */
14	public final class Sha256 {
15	
16	    private Sha256() {
17	    }
18	
19	    /** The full 64-character lower-case hex SHA-256 over the UTF-8 bytes of {@code value}. */
20	    public static String hex(String value) {
21	        try {
22	            byte[] digest = MessageDigest.getInstance("SHA-256")
23	                    .digest(value.getBytes(StandardCharsets.UTF_8));
24	            StringBuilder sb = new StringBuilder(digest.length * 2);
25	            for (byte b : digest) {
26	                sb.append(String.format("%02x", b));
27	            }
28	            return sb.toString();
29	        }
30	        catch (NoSuchAlgorithmException e) {
31	            throw new IllegalStateException("SHA-256 not available", e);
32	        }
33	    }
34	}
