5	/**
6	 * Derives an owner's numeric membership points.
7	 *
8	 * <p>Starts at 0; add 2 when an email is present; add 1 when {@code namesakeCount}
9	 * is 0; add 2 for a household of 3 or more; add 3 for tenure of at least one elapsed
10	 * fiscal year.
11	 */
12	public final class MembershipPoints {
13	
14	    /** Household size, at or above which the household bonus applies. */
15	    public static final int HOUSEHOLD_SIZE = 3;
16	
17	    /** Elapsed fiscal years the tenure must reach to earn the tenure bonus. */
18	    public static final int TENURE_FISCAL_YEARS = 1;
19	
20	    private MembershipPoints() {
21	    }
22	
23	    /** The membership points for the given owner. */
24	    public static int of(Owner owner) {
25	        int points = 0;
26	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
27	            points += 2;
28	        }
29	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
30	            points += 1;
31	        }
32	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_SIZE) {
33	            points += 2;
34	        }
35	        if (hasTenure(owner)) {
36	            points += 3;
37	        }
38	        return points;
39	    }
40	
41	    /** Whether at least {@link #TENURE_FISCAL_YEARS} fiscal years have elapsed since registration. */
42	    private static boolean hasTenure(Owner owner) {
43	        LocalDate registrationDate = owner.getRegistrationDate();
44	        if (registrationDate == null) {
45	            return false;
46	        }
47	        int elapsedFiscalYears = FiscalYear.yearOf(LocalDate.now()) - FiscalYear.yearOf(registrationDate);
48	        return elapsedFiscalYears >= TENURE_FISCAL_YEARS;
49	    }
50	}
